insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P073','classic-tiered-octagonal-fountain-120x120x60','fountains','نافورة كلاسيكية متعددة الطبقات 120×120×60 سم',130000,162500,'published',54,'{"currency":"SAR","images":["source-assets/generated-products/new-fountain-classic-tiered-octagonal-120x120x60.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"lengthCm":120,"widthCm":120,"heightCm":60},"features":["مصنوعة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا","إمكانية تخصيص المقاسات واختيار اللون المناسب للمشروع","إضاءة LED مدمجة حسب الطلب لإطلالة مميزة ليلًا","جاهزة للتشغيل بنظام تدوير مستمر ولا تحتاج إلى أعمال سباكة معقدة","إمكانية تجهيز نظام إعادة تعبئة ذاتي للمياه (ملء أوتوماتيكي)","مناسبة للأماكن الداخلية والخارجية","مقاومة للشمس والرطوبة والعوامل الجوية","خفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية"],"uses":["حدائق","أفنية","مداخل فلل","مساحات داخلية وخارجية"],"tags":["نافورة","كلاسيكية","متعددة الطبقات","حوض مثمن"],"relatedProducts":["AC-P087","AC-P089","AC-P076"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","originalPrice":1625,"category":"water-features","subcategory":"fountains","description":"أضف لمسة راقية إلى حديقتك أو فناء منزلك بتصميم أنيق يجمع بين الشكل العصري والبساطة العملية. صُنعت النافورة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا، وهي جاهزة للتشغيل بنظام تدوير مستمر للمياه ولا تحتاج إلى أعمال سباكة معقدة. يمكن تخصيص المقاسات واختيار اللون المناسب للمشروع، كما يمكن إضافة إضاءة LED ونظام تعبئة أوتوماتيكي حسب الطلب. النافورة مناسبة للأماكن الداخلية والخارجية، ومقاومة للشمس والرطوبة والعوامل الجوية، وخفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية.","isNewFountain":true,"id":"AC-P073","name":"نافورة كلاسيكية متعددة الطبقات 120×120×60 سم","slug":"classic-tiered-octagonal-fountain-120x120x60","price":1300,"image":"source-assets/generated-products/new-fountain-classic-tiered-octagonal-120x120x60.jpg","imageName":"new-fountain-classic-tiered-octagonal-120x120x60","alt":"نافورة كلاسيكية بيضاء متعددة الطبقات بحوض مثمن مقاس 120 في 120 وارتفاع 60 سم","shortDescription":"نافورة كلاسيكية متعددة الطبقات بحوض مثمن وتدفق مائي متدرج."}'::jsonb) on conflict(id) do nothing;
