insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P075','planter-form-fountain-54x70','fountains','نافورة على شكل مركن 54×70 سم',85000,106300,'published',56,'{"currency":"SAR","images":["source-assets/generated-products/new-fountain-planter-form-54x70.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"widthCm":54,"heightCm":70},"features":["مصنوعة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا","إمكانية تخصيص المقاسات واختيار اللون المناسب للمشروع","إضاءة LED مدمجة حسب الطلب لإطلالة مميزة ليلًا","جاهزة للتشغيل بنظام تدوير مستمر ولا تحتاج إلى أعمال سباكة معقدة","إمكانية تجهيز نظام إعادة تعبئة ذاتي للمياه (ملء أوتوماتيكي)","مناسبة للأماكن الداخلية والخارجية","مقاومة للشمس والرطوبة والعوامل الجوية","خفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية"],"uses":["حدائق","أفنية","مداخل فلل","مساحات داخلية وخارجية"],"tags":["نافورة","شكل مركن","مدمجة","مصب مركزي"],"relatedProducts":["AC-P084","AC-P085","AC-P086"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","originalPrice":1063,"category":"water-features","subcategory":"fountains","description":"أضف لمسة راقية إلى حديقتك أو فناء منزلك بتصميم أنيق يجمع بين الشكل العصري والبساطة العملية. صُنعت النافورة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا، وهي جاهزة للتشغيل بنظام تدوير مستمر للمياه ولا تحتاج إلى أعمال سباكة معقدة. يمكن تخصيص المقاسات واختيار اللون المناسب للمشروع، كما يمكن إضافة إضاءة LED ونظام تعبئة أوتوماتيكي حسب الطلب. النافورة مناسبة للأماكن الداخلية والخارجية، ومقاومة للشمس والرطوبة والعوامل الجوية، وخفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية.","isNewFountain":true,"id":"AC-P075","name":"نافورة على شكل مركن 54×70 سم","slug":"planter-form-fountain-54x70","price":850,"image":"source-assets/generated-products/new-fountain-planter-form-54x70.jpg","imageName":"new-fountain-planter-form-54x70","alt":"نافورة رماد