insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P079','rectangular-cascade-four-jet-fountain-190x80x90','fountains','نافورة مستطيلة بشلال وأربع مصبات 190×80×90 سم',310000,387500,'published',60,'{"currency":"SAR","images":["source-assets/generated-products/new-fountain-rectangular-cascade-190x80x90.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"lengthCm":190,"widthCm":80,"heightCm":90},"features":["مصنوعة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا","إمكانية تخصيص المقاسات واختيار اللون المناسب للمشروع","إضاءة LED مدمجة حسب الطلب لإطلالة مميزة ليلًا","جاهزة للتشغيل بنظام تدوير مستمر ولا تحتاج إلى أعمال سباكة معقدة","إمكانية تجهيز نظام إعادة تعبئة ذاتي للمياه (ملء أوتوماتيكي)","مناسبة للأماكن الداخلية والخارجية","مقاومة للشمس والرطوبة والعوامل الجوية","خفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية"],"uses":["حدائق","أفنية","مداخل فلل","مساحات داخلية وخارجية"],"tags":["نافورة","مستطيلة","شلال","أربعة مصبات"],"relatedProducts":["AC-P074","AC-P091","AC-P093"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","originalPrice":3875,"category":"water-features","subcategory":"fountains","description":"أضف لمسة راقية إلى حديقتك أو فناء منزلك بتصميم أنيق يجمع بين الشكل العصري والبساطة العملية. صُنعت النافورة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا، وهي جاهزة للتشغيل بنظام تدوير مستمر للمياه ولا تحتاج إلى أعمال سباكة معقدة. يمكن تخصيص المقاسات واختيار اللون المناسب للمشروع، كما يمكن إضافة إضاءة LED ونظام تعبئة أوتوماتيكي حسب الطلب. النافورة مناسبة للأماكن الداخلية والخارجية، ومقاومة للشمس والرطوبة والعوامل الجوية، وخفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية.","isNewFountain":true,"id":"AC-P079","name":"نافورة مستطيلة بشلال وأربع مصبات 190×80×90 سم","slug":"rectangular-cascade-four-jet-fountain-190x80x90","price":3100,"image":"source-assets/generated-products/new-fountain-rectangular-cascade-190x80x90.jpg","imageName":"new-fountain-rectangular-cascade-190x80x90","alt":"نافورة مستطيلة سوداء بشلال وأربع مصبات مقاس 190 في 80 وارتفاع 90 سم","shortDescription":"نافورة خطية سوداء تجمع شلالًا عريضًا مع أربعة مصبات علوية."}'::jsonb) on conflict(id) do nothing;
