insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P092','planter-waterfall-fountain-120x90x80','fountains','نافورة شلال مع حوض زراعي 120×90×80 سم',285000,356300,'published',73,'{"currency":"SAR","images":["source-assets/generated-products/new-fountain-planter-waterfall-120x90x80.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"lengthCm":120,"widthCm":90,"heightCm":80},"features":["مصنوعة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا","إمكانية تخصيص المقاسات واختيار اللون المناسب للمشروع","إضاءة LED مدمجة حسب الطلب لإطلالة مميزة ليلًا","جاهزة للتشغيل بنظام تدوير مستمر ولا تحتاج إلى أعمال سباكة معقدة","إمكانية تجهيز نظام إعادة تعبئة ذاتي للمياه (ملء أوتوماتيكي)","مناسبة للأماكن الداخلية والخارجية","مقاومة للشمس والرطوبة والعوامل الجوية","خفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية"],"uses":["حدائق","أفنية","مداخل فلل","مساحات داخلية وخارجية"],"tags":["نافورة","شلال","حوض زراعي","إضاءة"],"relatedProducts":["AC-P083","AC-P077","AC-P074"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","originalPrice":3563,"category":"water-features","subcategory":"fountains","description":"أضف لمسة راقية إلى حديقتك أو فناء منزلك بتصميم أنيق يجمع بين الشكل العصري والبساطة العملية. صُنعت النافورة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا، وهي جاهزة للتشغيل بنظام تدوير مستمر للمياه ولا تحتاج إلى أعمال سباكة معقدة. يمكن تخصيص المقاسات واختيار اللون المناسب للمشروع، كما يمكن إضافة إضاءة LED ونظام تعبئة أوتوماتيكي حسب الطلب. النافورة مناسبة للأماكن الداخلية والخارجية، ومقاومة للشمس والرطوبة والعوامل الجوية، وخفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية.","isNewFountain":true,"id":"AC-P092","name":"نافورة شلال مع حوض زراعي 120×90×80 سم","slug":"planter-waterfall-fountain-120x90x80","price":2850,"image":"source-assets/generated-products/new-fountain-planter-waterfall-120x90x80.jpg","imageName":"new-fountain-planter-waterfall-120x90x80","alt":"نافورة شلال سوداء مع حوض زراعي مقاس 120 في 90 وارتفاع 80 سم","shortDescription":"تكوين مدمج يجمع حوضًا زراعيًا علويًا وشلالًا مضاءً في تصميم عصري."}'::jsonb) on conflict(id) do nothing;
