insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P094','natural-tall-rattan-planter-34x64','rattan-bamboo','مركن روتان طبيعي طويل 34×64 سم',19000,23800,'published',75,'{"currency":"SAR","images":["source-assets/generated-products/new-rattan-planter-34x64.jpg"],"material":"روتان أو بامبو مع عزل داخلي من الفايبر جلاس","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"widthCm":34,"heightCm":64},"features":["تصميم عصري وفاخر يناسب مختلف أنماط تنسيق المواقع","مصنوع من الروتان الطبيعي أو البامبو ومعزول داخليًا بالفايبر جلاس عالي الجودة","متانة وعمر تشغيلي طويل","مناسب للاستخدام الداخلي والخارجي","خفيف وسهل النقل والتركيب","ألوان وتشطيبات متعددة حسب الطلب","مناسب للفلل والحدائق والاستراحات والمنتجعات والفنادق"],"uses":["فلل","حدائق","استراحات","منتجعات","فنادق","مساحات داخلية وخارجية"],"tags":["مركن","روتان طبيعي","طويل","نسيج متعرج"],"relatedProducts":["AC-P099","AC-P111","AC-P112"],"complementaryProducts":[],"availableColors":["طبيعي","عسلي","بني","بني داكن","أسود"],"seoTitle":"","seoDescription":"","originalPrice":238,"category":"planters","subcategory":"rattan-bamboo","description":"ارتقِ بجمال حديقتك أو مساحتك الخارجية مع مركن من الروتان أو البامبو من شركة تشييد العمارة العربية، بتصميم يجمع بين الأناقة والهدوء والجودة ليكون إضافة مميزة للفلل والاستراحات والمنتجعات والمشاريع الفندقية. صُمم المركن ليمنح المكان أجواءً هادئة ومريحة، ويتميز بكسوة من الروتان الطبيعي أو البامبو مع عزل داخلي من الفايبر جلاس عالي الجودة لمتانة وعمر تشغيلي طويل. يناسب الاستخدام الداخلي والخارجي، ويمكن اختيار اللون والتشطيب بما يتوافق مع تصميم المشروع.","isNewRattan":true,"id":"AC-P094","name":"مركن روتان طبيعي طويل 34×64 سم","slug":"natural-tall-rattan-planter-34x64","price":190,"image":"source-assets/generated-products/new-rattan-planter-34x64.jpg","imageName":"new-rattan-planter-34x64","alt":"مركن روتان طبيعي طويل بعرض 34 سم وارتفاع 64 سم","shortDescription":"مركن روتان طويل بنسيج متعرج ولون طبيعي داكن."}'::jso