insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P112','tall-woven-bamboo-planter-35x60','rattan-bamboo','مركن بامبو طويل بمقابض 35×60 سم',19000,23800,'published',93,'{"currency":"SAR","images":["source-assets/generated-products/new-rattan-planter-35x60.jpg"],"material":"روتان أو بامبو مع عزل داخلي من الفايبر جلاس","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"widthCm":35,"heightCm":60},"features":["تصميم عصري وفاخر يناسب مختلف أنماط تنسيق المواقع","مصنوع من الروتان الطبيعي أو البامبو ومعزول داخليًا بالفايبر جلاس عالي الجودة","متانة وعمر تشغيلي طويل","مناسب للاستخدام الداخلي والخارجي","خفيف وسهل النقل والتركيب","ألوان وتشطيبات متعددة حسب الطلب","مناسب للفلل والحدائق والاستراحات والمنتجعات والفنادق"],"uses":["فلل","حدائق","استراحات","منتجعات","فنادق","مساحات داخلية وخارجية"],"tags":["مركن","بامبو","طويل","مقابض"],"relatedProducts":["AC-P111","AC-P094","AC-P096"],"complementaryProducts":[],"availableColors":["طبيعي","عسلي","بني","بني داكن","أسود"],"seoTitle":"","seoDescription":"","originalPrice":238,"category":"planters","subcategory":"rattan-bamboo","description":"ارتقِ بجمال حديقتك أو مساحتك الخارجية مع مركن من الروتان أو البامبو من شركة تشييد العمارة العربية، بتصميم يجمع بين الأناقة والهدوء والجودة ليكون إضافة مميزة للفلل والاستراحات والمنتجعات والمشاريع الفندقية. صُمم المركن ليمنح المكان أجواءً هادئة ومريحة، ويتميز بكسوة من الروتان الطبيعي أو البامبو مع عزل داخلي من الفايبر جلاس عالي الجودة لمتانة وعمر تشغيلي طويل. يناسب الاستخدام الداخلي والخارجي، ويمكن اختيار اللون والتشطيب بما يتوافق مع تصميم المشروع.","isNewRattan":true,"id":"AC-P112","name":"مركن بامبو طويل بمقابض 35×60 سم","slug":"tall-woven-bamboo-planter-35x60","price":190,"image":"source-assets/generated-products/new-rattan-planter-35x60.jpg","imageName":"new-rattan-planter-35x60","alt":"مركن بامبو طبيعي طويل بمقابض بعرض 35 سم وارتفاع 60 سم","shortDescription":"مركن بامبو طويل بنسيج متعرج ومقابض علوية عملية."}'::jsonb) on conflict(id) do nothing;
