insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P113','ornate-classic-three-tier-fountain-125x220','fountains','نافورة كلاسيكية زخرفية ثلاثية الطبقات ⁦125×220⁩ سم',345000,431300,'published',94,'{"currency":"SAR","images":["source-assets/generated-products/new-fountain-ornate-three-tier-125x220.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"widthCm":125,"heightCm":220},"features":["مصنوعة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا","إمكانية تخصيص المقاسات واختيار اللون المناسب للمشروع","إضاءة LED مدمجة حسب الطلب لإطلالة مميزة ليلًا","جاهزة للتشغيل بنظام تدوير مستمر ولا تحتاج إلى أعمال سباكة معقدة","إمكانية تجهيز نظام إعادة تعبئة ذاتي للمياه (ملء أوتوماتيكي)","مناسبة للأماكن الداخلية والخارجية","مقاومة للشمس والرطوبة والعوامل الجوية","خفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية"],"uses":["حدائق","أفنية","مداخل فلل","مساحات داخلية وخارجية"],"tags":["نافورة","كلاسيكية","زخرفية","ثلاث طبقات"],"relatedProducts":["AC-P087","AC-P073","AC-P089"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","originalPrice":4313,"category":"water-features","subcategory":"fountains","description":"أضف لمسة راقية إلى حديقتك أو فناء منزلك بتصميم أنيق يجمع بين الشكل العصري والبساطة العملية. صُنعت النافورة بالكامل من فايبر جلاس عالي الجودة لمتانة تدوم طويلًا، وهي جاهزة للتشغيل بنظام تدوير مستمر للمياه ولا تحتاج إلى أعمال سباكة معقدة. يمكن تخصيص المقاسات واختيار اللون المناسب للمشروع، كما يمكن إضافة إضاءة LED ونظام تعبئة أوتوماتيكي حسب الطلب. النافورة مناسبة للأماكن الداخلية والخارجية، ومقاومة للشمس والرطوبة والعوامل الجوية، وخفيفة الوزن وسهلة النقل مقارنة بالبدائل الحجرية.","isNewFountain":true,"id":"AC-P113","name":"نافورة كلاسيكية زخرفية ثلاثية الطبقات ⁦125×220⁩ سم","slug":"ornate-classic-three-tier-fountain-125x220","price":3450,"image":"source-assets/generated-products/new-fountain-ornate-three-tier-125x220.jpg","imageName":"new-fountain-ornate-three-tier-125x220","alt":"نافورة كلاسيكية بيضاء زخرفية ثلاثية الطبقات بعرض 125 سم وارتفاع 220 سم","shortDescription":"نافورة كلاسيكية شاهقة بثلاث طبقات وتفاصيل زخرفية فاخرة."}'::jsonb) on conflict(id) do nothing;
