ألوان متعددة.","isNewRoundPlanter":true,"id":"AC-P115","name":"حوض زراعة دائري أملس مقاس ⁦40×70⁩ سم","slug":"round-smooth-planter-40x70","price":290,"image":"source-assets/generated-products/round/new-round-smooth-40x70.jpg","imageName":"new-round-smooth-40x70","alt":"حوض زراعة دائري أملس بعرض 40 سم وارتفاع 70 سم"}'::jsonb) on conflict(id) do nothing;
