insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P128','round-heritage-planter-36x52','round','حوض زراعة دائري تراثي مقاس ⁦36×52⁩ سم',21000,null,'published',109,'{"currency":"SAR","images":["source-assets/customer-product-photos/ac-p128-a81de549.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"متوسط","dimensions":{"widthCm":36,"heightCm":52},"features":["تصميم دائري عصري يناسب مختلف الأنماط المعمارية","مصنوع من الفايبر جلاس عالي الجودة","خفيف الوزن ومتين وسهل النقل","مناسب للزراعة الطبيعية والصناعية","ملائم للاستخدام الداخلي والخارجي","مقاوم للرطوبة والعوامل الجوية","متوفر بعدة مقاسات وألوان لتلبية احتياجات المشاريع المختلفة","إمكانية تخصيص اللون والتشطيب","إمكانية إضافة فتحات تصريف للمياه عند استخدامه للزراعة الطبيعية","يساعد على إبراز جمالية المساحات وتنسيق النباتات بأسلوب متناسق"],"uses":["الحدائق المنزلية","مداخل الفلل والقصور","الممرات","الشرفات","الفنادق","المطاعم","المكاتب","المجمعات التجارية","المشاريع السكنية","المشاريع المعمارية والتنسيقية"],"tags":["تراثي"],"relatedProducts":["AC-P132","AC-P133","AC-P134"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","category":"planters","subcategory":"round","description":"يتميز حوض الزراعة الدائري من شركة تشييد العمارة بتصميم عصري أنيق وخطوط انسيابية ناعمة تضفي لمسة جمالية مميزة على المساحات الداخلية والخارجية.","secondaryDescription":"يجمع الحوض بين البساطة والفخامة، مما يجعله خيارًا مثاليًا لتنسيق الحدائق، ومداخل الفلل، والفنادق، والمجمعات التجارية، والمشاريع السكنية. كما يتوفر بعدة مقاسات وألوان تتيح تنسيقه بما يتناسب مع مختلف التصاميم المعمارية. يُصنع الحوض من الفايبر جلاس عالي الجودة، الذي يتميز بخفة الوزن والمتانة، مع مقاومة مناسبة للرطوبة والعوامل الجوية، مما يجعله ملائمًا للاستخدام الداخلي والخارجي، مع سهولة النقل والتنظيف والمحافظة على مظهره الأنيق لفترات طويلة.","shortDescription":"حوض زراعة دائري من الفايبر جلاس بتصميم عصري وخيارات ألوان متعددة.","isNewRoundPlanter":true,"id":"AC-P128","name":"حوض زراعة دائري تراثي مقاس ⁦36×52⁩ سم","slug":"round-heritage-planter-36x52","price":210,"image":"source-assets/customer-product-photos/ac-p128-a81de549.jpg","imageName":"new-round-heritage-36x52","alt":"حوض زراعة دائري تراثي بعرض 36 سم وارتفاع 52 سم"}'::jsonb) on conflict(id) do nothing;
