insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P144','round-ribbed-medium-planter-30x32','round','حوض زراعة دائري مخطط وسط مقاس ⁦30×32⁩ سم',10000,null,'published',125,'{"currency":"SAR","images":["source-assets/customer-product-photos/ac-p144-45ae0411.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"صغير","dimensions":{"widthCm":30,"heightCm":32},"features":["تصميم دائري عصري يناسب مختلف الأنماط المعمارية","مصنوع من الفايبر جلاس عالي الجودة","خفيف الوزن ومتين وسهل النقل","مناسب للزراعة الطبيعية والصناعية","ملائم للاستخدام الداخلي والخارجي","مقاوم للرطوبة والعوامل الجوية","متوفر بعدة مقاسات وألوان لتلبية احتياجات المشاريع المختلفة","إمكانية تخصيص اللون والتشطيب","إمكانية إضافة فتحات تصريف للمياه عند استخدامه للزراعة الطبيعية","يساعد على إبراز جمالية المساحات وتنسيق النباتات بأسلوب متناسق"],"uses":["الحدائق المنزلية","مداخل الفلل والقصور","الممرات","الشرفات","الفنادق","المطاعم","المكاتب","المجمعات التجارية","المشاريع السكنية","المشاريع المعمارية والتنسيقية"],"tags":["مخطط","وسط"],"relatedProducts":["AC-P132","AC-P133","AC-P134"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","category":"planters","subcategory":"round","description":"يتميز حوض الزراعة الدائري من شركة تشييد العمارة بتصميم عصري أنيق وخطوط انسيابية ناعمة تضفي لمسة جمالية مميزة على المساحات الداخلية والخارجية.","secondaryDescription":"يجمع الحوض بين البساطة والفخامة، مما يجعله خيارًا مثاليًا لتنسيق الحدائق، ومداخل الفلل، والفنادق، والمجمعات التجارية، والمشاريع السكنية. كما يتوفر بعدة مقاسات وألوان تتيح تنسيقه بما يتناسب مع مختلف التصاميم المعمارية. يُصنع الحوض من الفايبر جلاس عالي الجودة، الذي يتميز بخفة الوزن والمتانة، مع مقاومة مناسبة للرطوبة والعوامل الجوية، مما يجعله ملائمًا للاستخدام الداخلي والخارجي، مع سهولة النقل والتنظيف والمحافظة على مظهره الأنيق لفترات طويلة.","shortDescription":"حوض زراعة دائري من الفايبر جلاس بتصميم عصري وخيارات ألوان متعددة.","isNewRoundPlanter":true,"id":"AC-P144","name":"حوض زراعة دائري مخطط وسط مقاس ⁦30×32⁩ سم","slug":"round-ribbed-medium-planter-30x32","price":100,"image":"source-assets/customer-product-photos/ac-p144-45ae0411.jpg","imageName":"new-round-ribbed-medium-30x32","alt":"حوض زراعة دائري مخطط وسط بعرض 30 سم وارتفاع 32 سم"}'::jsonb) on conflict(id) do nothing;
