insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P156','oval-engraved-medium-40x40','oval','حوض زراعة بيضاوي مقاس ⁦40×40⁩ سم',15000,null,'published',137,'{"currency":"SAR","images":["source-assets/customer-product-photos/ac-p156-e965009a.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"صغير","dimensions":{"widthCm":40,"heightCm":40},"features":["تصميم بيضاوي عصري يناسب مختلف الأنماط المعمارية","مصنوع من الفايبر جلاس عالي الجودة","خفيف الوزن ومتين وسهل النقل","مناسب للزراعة الطبيعية والصناعية","ملائم للاستخدام الداخلي والخارجي","مقاوم للرطوبة والعوامل الجوية","متوفر بعدة مقاسات وألوان لتلبية احتياجات المشاريع المختلفة","إمكانية تخصيص اللون والتشطيب","إمكانية إضافة فتحات تصريف للمياه عند استخدامه للزراعة الطبيعية","يساعد على إبراز جمالية المساحات وتنسيق النباتات بأسلوب متناسق"],"uses":["الحدائق المنزلية","مداخل الفلل والقصور","الممرات","الشرفات","الفنادق","المطاعم","المكاتب","المجمعات التجارية","المشاريع السكنية","المشاريع المعمارية والتنسيقية"],"tags":["محفور","وسط"],"relatedProducts":["AC-P154","AC-P155","AC-P156"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","category":"planters","subcategory":"oval","description":"يتميز حوض الزراعة البيضاوي من شركة تشييد العمارة بتصميم عصري أنيق وخطوط انسيابية ناعمة تضفي لمسة جمالية مميزة على المساحات الداخلية والخارجية.","secondaryDescription":"يجمع الحوض بين البساطة والفخامة، مما يجعله خيارًا مثاليًا لتنسيق الحدائق، ومداخل الفلل، والفنادق، والمجمعات التجارية، والمشاريع السكنية. كما يتوفر بعدة مقاسات وألوان تتيح تنسيقه بما يتناسب مع مختلف التصاميم المعمارية. يُصنع الحوض من الفايبر جلاس عالي الجودة، الذي يتميز بخفة الوزن والمتانة، مع مقاومة مناسبة للرطوبة والعوامل الجوية، مما يجعله ملائمًا للاستخدام الداخلي والخارجي، مع سهولة النقل والتنظيف والمحافظة على مظهره الأنيق لفترات طويلة.","shortDescription":"حوض زراعة بيضاوي من الفايبر جلاس بتصميم عصري وخيارات ألوان متعددة. السعر شامل الضريبة.","isNewOvalPlanter":true,"id":"AC-P156","name":"حوض زراعة بيضاوي مقاس ⁦40×40⁩ سم","slug":"oval-engraved-medium-40x40","price":150,"image":"source-assets/customer-product-photos/ac-p156-e965009a.jpg","imageName":"oval-engraved-medium-40x40","alt":"حوض زراعة بيضاوي محفور بعرض 40 سم وارتفاع 40 سم"}'::jsonb) on conflict(id) do nothing;
