insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P160','oval-urn-black-41x60','oval','حوض زراعة بيضاوي مقاس ⁦41×60⁩ سم',26000,null,'published',141,'{"currency":"SAR","images":["source-assets/generated-products/oval/oval-urn-black-41x60.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"متوسط","dimensions":{"widthCm":41,"heightCm":60},"features":["تصميم بيضاوي عصري يناسب مختلف الأنماط المعمارية","مصنوع من الفايبر جلاس عالي الجودة","خفيف الوزن ومتين وسهل النقل","مناسب للزراعة الطبيعية والصناعية","ملائم للاستخدام الداخلي والخارجي","مقاوم للرطوبة والعوامل الجوية","متوفر بعدة مقاسات وألوان لتلبية احتياجات المشاريع المختلفة","إمكانية تخصيص اللون والتشطيب","إمكانية إضافة فتحات تصريف للمياه عند استخدامه للزراعة الطبيعية","يساعد على إبراز جمالية المساحات وتنسيق النباتات بأسلوب متناسق"],"uses":["الحدائق المنزلية","مداخل الفلل والقصور","الممرات","الشرفات","الفنادق","المطاعم","المكاتب","المجمعات التجارية","المشاريع السكنية","المشاريع المعمارية والتنسيقية"],"tags":["شكل جرة","أسود"],"relatedProducts":["AC-P154","AC-P155","AC-P156"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","category":"planters","subcategory":"oval","description":"يتميز حوض الزراعة البيضاوي من شركة تشييد العمارة بتصميم عصري أنيق وخطوط انسيابية ناعمة تضفي لمسة جمالية مميزة على المساحات الداخلية والخارجية.","secondaryDescription":"يجمع الحوض بين البساطة والفخامة، مما يجعله خيارًا مثاليًا لتنسيق الحدائق، ومداخل الفلل، والفنادق، والمجمعات التجارية، والمشاريع السكنية. كما يتوفر بعدة مقاسات وألوان تتيح تنسيقه بما يتناسب مع مختلف التصاميم المعمارية. يُصنع الحوض من الفايبر جلاس عالي الجودة، الذي يتميز بخفة الوزن والمتانة، مع مقاومة مناسبة للرطوبة والعوامل الجوية، مما يجعله ملائمًا للاستخدام الداخلي والخارجي، مع سهولة النقل والتنظيف والمحافظة على مظهره الأنيق لفترات طويلة.","shortDescription":"حوض زراعة بيضاوي من الفايبر جلاس بتصميم عصري وخيارات ألوان متعددة. السعر شامل الضريبة.","isNewOvalPlanter":true,"id":"AC-P160","name":"حوض زراعة بيضاوي مقاس ⁦41×60⁩ سم","slug":"oval-urn-black-41x60","price":260,"image":"source-assets/generated-products/oval/oval-urn-black-41x60.jpg","imageName":"oval-urn-black-41x60","alt":"حوض زراعة بيضاوي أسود بشكل جرة بعرض 41 سم وارتفاع 60 سم"}'::jsonb) on conflict(id) do nothing;
