insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P188','oval-tall-ribbed-brown-43x70','oval','حوض زراعة بيضاوي مقاس ⁦43×70⁩ سم',23000,null,'published',169,'{"currency":"SAR","images":["source-assets/customer-product-photos/ac-p188-be0d7b7d.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"متوسط","dimensions":{"widthCm":43,"heightCm":70},"features":["تصميم بيضاوي عصري يناسب مختلف الأنماط المعمارية","مصنوع من الفايبر جلاس عالي الجودة","خفيف الوزن ومتين وسهل النقل","مناسب للزراعة الطبيعية والصناعية","ملائم للاستخدام الداخلي والخارجي","مقاوم للرطوبة والعوامل الجوية","متوفر بعدة مقاسات وألوان لتلبية احتياجات المشاريع المختلفة","إمكانية تخصيص اللون والتشطيب","إمكانية إضافة فتحات تصريف للمياه عند استخدامه للزراعة الطبيعية","يساعد على إبراز جمالية المساحات وتنسيق النباتات بأسلوب متناسق"],"uses":["الحدائق المنزلية","مداخل الفلل والقصور","الممرات","الشرفات","الفنادق","المطاعم","المكاتب","المجمعات التجارية","المشاريع السكنية","المشاريع المعمارية والتنسيقية"],"tags":["مخطط","بني"],"relatedProducts":["AC-P154","AC-P155","AC-P156"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","category":"planters","subcategory":"oval","description":"يتميز حوض الزراعة البيضاوي من شركة تشييد العمارة بتصميم عصري أنيق وخطوط انسيابية ناعمة تضفي لمسة جمالية مميزة على المساحات الداخلية والخارجية.","secondaryDescription":"يجمع الحوض بين البساطة والفخامة، مما يجعله خيارًا مثاليًا لتنسيق الحدائق، ومداخل الفلل، والفنادق، والمجمعات التجارية، والمشاريع السكنية. كما يتوفر بعدة مقاسات وألوان تتيح تنسيقه بما يتناسب مع مختلف التصاميم المعمارية. يُصنع الحوض من الفايبر جلاس عالي الجودة، الذي يتميز بخفة الوزن والمتانة، مع مقاومة مناسبة للرطوبة والعوامل الجوية، مما يجعله ملائمًا للاستخدام الداخلي والخارجي، مع سهولة النقل والتنظيف والمحافظة على مظهره الأنيق لفترات طويلة.","shortDescription":"حوض زراعة بيضاوي من الفايبر جلاس بتصميم عصري وخيارات ألوان متعددة. السعر شامل الضريبة.","isNewOvalPlanter":true,"id":"AC-P188","name":"حوض زراعة بيضاوي مقاس ⁦43×70⁩ سم","slug":"oval-tall-ribbed-brown-43x70","price":230,"image":"source-assets/customer-product-photos/ac-p188-be0d7b7d.jpg","imageName":"oval-tall-ribbed-brown-43x70","alt":"حوض زراعة بيضاوي طويل مخطط باللون البني بعرض 43 سم وارتفاع 70 سم"}'::jsonb) on conflict(id) do nothing;
