insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P202','wall-waterfall-sheet-110x230','waterfalls','شلال جداري متحرك انسيابي بمصب مقاس ⁦110×230⁩ سم',345000,431300,'published',183,'{"currency":"SAR","images":["source-assets/generated-products/waterfalls/wall-waterfall-sheet-110x230.png"],"material":"فايبر جلاس معزز","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"widthCm":110,"heightCm":230},"features":["تصميم عصري وفاخر يناسب مختلف أنماط تنسيق المواقع","مصنوع من الفايبر جلاس عالي الجودة لمتانة وعمر تشغيلي طويل","مناسب للاستخدام الداخلي والخارجي","نظام لتدوير المياه بشكل مستمر","إضاءة LED مدمجة لإطلالة مميزة ليلًا حسب الطلب","سهل التركيب والتشغيل","إمكانية اختيار اللون بما يتناسب مع تصميم المشروع","مناسب للفلل والحدائق والاستراحات والمنتجعات والفنادق"],"uses":["فلل","حدائق","استراحات","منتجعات","فنادق"],"tags":["شلال","جداري","مصب","انسيابي"],"relatedProducts":["AC-P192","AC-P193","AC-P197"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","originalPrice":4313,"category":"water-features","subcategory":"waterfalls","description":"شلال انسيابي فاخر بتصميم يجمع بين الأناقة والهدوء والجودة، ليكون إضافة مميزة للفلل والاستراحات والمنتجعات والمشاريع الفندقية. صُمم بتدفق مائي انسيابي يمنح المكان أجواءً هادئة ومريحة، مع إمكانية إضافة إضاءة LED مدمجة حسب الطلب لإطلالة مميزة ليلًا. الشلال ليس مجرد عنصر ديكوري، بل قطعة تضيف الحركة والصوت والإضاءة إلى المكان وترفع من القيمة الجمالية للمساحة.","isNewWaterfall":true,"id":"AC-P202","name":"شلال جداري متحرك انسيابي بمصب مقاس ⁦110×230⁩ سم","slug":"wall-waterfall-sheet-110x230","price":3450,"image":"source-assets/generated-products/waterfalls/wall-waterfall-sheet-110x230.png","imageName":"wall-waterfall-sheet-110x230","alt":"شلال جداري متحرك انسيابي بمصب بعرض 110 سم وارتفاع 230 سم","shortDescription":"شلال جداري متحرك طويل بمصب علوي وتدفق مائي انسيابي."}'::jsonb) on conflict(id) do nothing;
