insert into public.products(id,slug,category_id,name,price_minor,compare_at_price_minor,status,sort_order,details) values ('AC-P206','spherical-large-black-80x72','spherical','حوض زراعة كروي كبير مقاس ⁦80×72⁩ سم',42000,null,'published',187,'{"currency":"SAR","images":["source-assets/generated-products/spherical/spherical-large-black-80x72.jpg"],"material":"فايبر جلاس عالي الجودة","color":"متعدد حسب الطلب","size":"كبير","dimensions":{"widthCm":80,"heightCm":72},"features":["تصميم كروي عصري يناسب مختلف الأنماط المعمارية","مصنوع من الفايبر جلاس عالي الجودة","خفيف الوزن ومتين وسهل النقل","مناسب للزراعة الطبيعية والصناعية","ملائم للاستخدام الداخلي والخارجي","مقاوم للرطوبة والعوامل الجوية","متوفر بعدة مقاسات وألوان لتلبية احتياجات المشاريع المختلفة","إمكانية تخصيص اللون والتشطيب","إمكانية إضافة فتحات تصريف للمياه عند استخدامه للزراعة الطبيعية","يساعد على إبراز جمالية المساحات وتنسيق النباتات بأسلوب متناسق"],"uses":["الحدائق المنزلية","مداخل الفلل والقصور","الممرات","الشرفات","الفنادق","المطاعم","المكاتب","المجمعات التجارية","المشاريع السكنية","المشاريع المعمارية والتنسيقية"],"tags":["كروي","أسود","كبير"],"relatedProducts":["AC-P203","AC-P204","AC-P205"],"complementaryProducts":[],"availableColors":["رمادي","ترابي","بيج","سكري","أسود"],"seoTitle":"","seoDescription":"","category":"planters","subcategory":"spherical","description":"يتميز حوض الزراعة الكروي من شركة تشييد العمارة بتصميم عصري أنيق وخطوط انسيابية ناعمة تضفي لمسة جمالية مميزة على المساحات الداخلية والخارجية.","secondaryDescription":"يجمع الحوض بين البساطة والفخامة، مما يجعله خيارًا مثاليًا لتنسيق الحدائق، ومداخل الفلل، والفنادق، والمجمعات التجارية، والمشاريع السكنية. كما يتوفر بعدة مقاسات وألوان تتيح تنسيقه بما يتناسب مع مختلف التصاميم المعمارية. يُصنع الحوض من الفايبر جلاس عالي الجودة، الذي يتميز بخفة الوزن والمتانة، مع مقاومة مناسبة للرطوبة والعوامل الجوية، مما يجعله ملائمًا للاستخدام الداخلي والخارجي، مع سهولة النقل والتنظيف والمحافظة على مظهره الأنيق لفترات طويلة.","shortDescription":"حوض زراعة كروي أو نصف كروي من الفايبر جلاس بتصميم عصري وخيارات ألوان متعددة.","isNewSphericalPlanter":true,"id":"AC-P206","name":"حوض زراعة كروي كبير مقاس ⁦80×72⁩ سم","slug":"spherical-large-black-80x72","price":420,"image":"source-assets/generated-products/spherical/spherical-large-black-80x72.jpg","imageName":"spherical-large-black-80x72","alt":"حوض زراعة كروي أسود كبير بعرض 80 سم وارتفاع 72 سم"}'::jsonb) on conflict(id) do nothing;
